package com.aadil.ecommerce.entities;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.UpdateTimestamp;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Table(name = "product_table")@Entity@Getter@Setter@NoArgsConstructorpublic class ProductEntity {    @GeneratedValue(strategy = GenerationType.IDENTITY)    @Id    @Column(name = "id")    private Long productId;    @Column(nullable = false)    private String productName;    @Column(nullable = false)    private String description;    @Column(nullable = false)    private BigDecimal price;    @Column(nullable = false)    private Integer stockQuantity;    @OneToMany(mappedBy = "product")    List<OrderItemEntity> orderItems = new ArrayList<>();    @Column(nullable = false)    private String category;    @CreationTimestamp    @Column(nullable = false,updatable = false)    private LocalDateTime createdAt;    @UpdateTimestamp    @Column(nullable = false)    private LocalDateTime updatedAt;}